20	struct RuntimeMeasurePoint {
21	    std::string          setting_label;          // dyn. Belegung "axis.var=value/…"
22	    std::uint64_t        repeat_index       = 0; // 0..repeats-1 (separate Roh-Messung, KF-10)
23	    std::uint64_t        applied_axis_count = 0; // real angewandte Resource-Control-Achsen
24	    NodeObserverSnapshot observer{};             // tier_observe-Ergebnis (echt getrieben)
25	};
