27	/// HostMeasureLoop — die host-seitige Mess-Schleife je geladener Binary. CMD-1 (d) (#267, 2026-07-06):
28	/// umbenannt von RuntimeMeasureVisitor — das Etikett war irrefuehrend (kein GoF-Visitor, kein accept/visit-
29	/// Double-Dispatch; K10-Disclaimer wortgleich). TierT erfüllt
30	/// IResourceControllableTier (für den Loop) UND IObservableTier (tier_insert/lookup/observe).
31	class HostMeasureLoop {
32	public:
33	    explicit HostMeasureLoop(anatomy::ComdareResourceControlV1 env_limits = {}) noexcept : env_{env_limits} {}
34	
35	    template <class TierT>
36	    [[nodiscard]] std::vector<RuntimeMeasurePoint> measure(TierT& tier, std::vector<DynamicDim> const& dims,
37	                                                           std::uint64_t n_ops, std::uint64_t repeats = 3) const {
38	        std::vector<RuntimeMeasurePoint> points;
39	        RuntimeVariableLoop              loop{env_};
40	        loop.run(tier, dims, [&](RuntimeSetting const& s) {
41	            for (std::uint64_t r = 0; r < repeats; ++r) {
42	                // Workload je Einstellung (RAM-resident, <1s): insert + lookup über die geladene Binary (kein Reload).
43	                for (std::uint64_t i = 0; i < n_ops; ++i) (void)tier.tier_insert(i, i * 7u + 1u);
44	                for (std::uint64_t i = 0; i < n_ops; ++i) {
45	                    std::uint64_t v = 0;
46	                    (void)tier.tier_lookup(i, &v);
47	                }
48	                anatomy::ComdareTierObserverSnapshot pod{};
49	                tier.tier_observe(&pod); // echter Observer-Snapshot (korreliert mit der Einstellung)
50	                RuntimeMeasurePoint p;
51	                p.setting_label      = s.setting_label;
52	                p.repeat_index       = r;
53	                p.applied_axis_count = s.applied_axis_count;
54	                // I1: V1-Projektion aus dem konsolidierten POD (search→axis_stats[0], alloc→axis_stats[6]).
55	                p.observer.search_lookup_count      = pod.axis_stats[0][0];
56	                p.observer.search_hit_count         = pod.axis_stats[0][1];
57	                p.observer.search_miss_count        = pod.axis_stats[0][2];
58	                p.observer.search_insert_count      = pod.axis_stats[0][3];
59	                p.observer.search_erase_count       = pod.axis_stats[0][4];
60	                p.observer.search_peak_occupancy    = pod.axis_stats[0][5];
61	                p.observer.alloc_bytes_allocated    = pod.axis_stats[6][0];
62	                p.observer.alloc_bytes_in_use       = pod.axis_stats[6][1];
63	                p.observer.alloc_allocation_count   = pod.axis_stats[6][2];
64	                p.observer.alloc_deallocation_count = pod.axis_stats[6][3];
65	                p.observer.alloc_failure_count      = pod.axis_stats[6][4];
66	                p.observer.observable_axis_count    = pod.observable_axis_count;
67	                p.observer.tier_fill_level          = pod.tier_fill_level;
68	                points.push_back(std::move(p));
69	            }
70	        });
71	        return points;
72	    }
